import enum
import logging
from taf.internal.managedobject import ManagedObject
from taf.trafficgenerator.iperf.factory import (IperfHostFactory, IperfFactory,
                                                Iperf2ServerOptionsFactory, Iperf2ClientOptionsFactory,
                                                Iperf3ServerOptionsFactory, Iperf3ClientOptionsFactory)
from taf.trafficgenerator.iperf.traffic_generator import IperfServerTrafficGenerator, IperfClientTrafficGenerator


class StopPrior(enum.Enum):
    Client = 1
    Server = 2
    NA = 0


class IperfFacade(ManagedObject):

    def __init__(self, logger=None):
        super(IperfFacade, self).__init__()
        self._logger = logger or logging
        self._iperf_host_factory = IperfHostFactory(self._logger)
        self._iperf_factory = IperfFactory(self._logger)
        self._iperf2_server_options_factory = Iperf2ServerOptionsFactory(self._logger)
        self._iperf2_client_options_factory = Iperf2ClientOptionsFactory(self._logger)
        self._iperf3_server_options_factory = Iperf3ServerOptionsFactory(self._logger)
        self._iperf3_client_options_factory = Iperf3ClientOptionsFactory(self._logger)

    def create_iperf_server(self,
                            cmd_options=None,
                            iperf_path=None,
                            adb=None,
                            serial_number=None,
                            host_configuration=None,
                            log_path=None,
                            host=None):
        """
        Create iperf server instance.

        :param cmd_options: (optional) iperf software options string or dictionary except for optional -s/server
        which is built-in from this Keyword
        dict:
                udp, interval, port, bandwidth, len, interval, bind, time, format, ipv6_domain, window, realtime,
                print_mss, mss nodelay, tos, udp-counters-64bit
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g. Create Dictionary
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx
        string:
            e.g. -u -i 1 -p 12345 -t 100
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost.
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param host: subclass of IperfHost
        :type host: IperfHost
        :return: iperf server instance
        """
        iperf_path = iperf_path or 'iperf'
        iperf_host = host or self._iperf_host_factory.create(host_configuration)
        iperf_options = self._iperf2_server_options_factory.create(iperf_path,
                                                                   cmd_options,
                                                                   adb=adb,
                                                                   serial_number=serial_number)
        return self._iperf_factory.create(iperf_host, iperf_options, log_path)

    def create_iperf_client(self,
                            cmd_options,
                            iperf_path=None,
                            adb=None,
                            serial_number=None,
                            host_configuration=None,
                            log_path=None,
                            host=None):
        """
        Create iperf client instance.

        :param cmd_options: iperf software options string or dictionary
        dict:
                mandatory iperf software options: client
                optional iperf software options: udp, port, bandwidth, len, interval, bind, time, format, ipv6_domain,
                window, print_mss, mss, nodelay, tos, parallel, dualtest, ttl
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  client=xxx.xxx.xxx.xxx
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx
        string:
                e.g. -u -c xxx.xxx.xxx.xxx -i 1 -p 54000 -b 5000k -t 120 -l 1000 -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param host: subclass of IperfHost
        :type host: IperfHost
        :return: iperf client instance
        """
        if not cmd_options:
            raise AttributeError('cmd_options cannot be None or empty for a client, -c/--client/client is required')
        iperf_path = iperf_path or 'iperf'
        iperf_host = host or self._iperf_host_factory.create(host_configuration)
        iperf_options = self._iperf2_client_options_factory.create(iperf_path,
                                                                   cmd_options,
                                                                   adb=adb,
                                                                   serial_number=serial_number)
        return self._iperf_factory.create(iperf_host, iperf_options, log_path)

    def create_iperf3_server(self,
                             cmd_options=None,
                             iperf_path=None,
                             adb=None,
                             serial_number=None,
                             host_configuration=None,
                             log_path=None,
                             host=None):
        """
        Create iperf server instance.

        :param cmd_options: (optional) iperf software options string or dictionary except for -s/server
        which is built-in from this Keyword
        dict:
                interval, bind, format, port
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  bind=xxx.xxx.xxx.xxx

        string: e.g. -i 1 -p 54000 -b 5000k -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param host: subclass of IperfHost
        :type host: IperfHost
        :return: iperf server instance
        """
        iperf_path = iperf_path or 'iperf'
        iperf_host = host or self._iperf_host_factory.create(host_configuration)
        iperf_options = self._iperf3_server_options_factory.create(iperf_path,
                                                                   cmd_options,
                                                                   adb=adb,
                                                                   serial_number=serial_number)
        return self._iperf_factory.create(iperf_host, iperf_options, log_path)

    def create_iperf3_client(self,
                             cmd_options,
                             iperf_path=None,
                             adb=None,
                             serial_number=None,
                             host_configuration=None,
                             log_path=None,
                             host=None):
        """
        Create iperf client instance.

        :param cmd_options: iperf software options string or dictionary
        dict:
                mandatory iperf software options: client
                optional iperf software options: udp, port, bitrate, length, interval, bind, time, format, window,
                set_mss, no_delay, tos, parallel, reverse
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  bind=xxx.xxx.xxx.xxx
        string: e.g. -u -p 540000 -i 1 -b 5000k -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param host: subclass of IperfHost
        :type host: IperfHost
        :return: iperf client instance
        """
        if not cmd_options:
            raise AttributeError('cmd_options cannot be None or empty for a client, -c/--client/client is required')
        iperf_path = iperf_path or 'iperf'
        iperf_host = host or self._iperf_host_factory.create(host_configuration)
        iperf_options = self._iperf3_client_options_factory.create(iperf_path,
                                                                   cmd_options,
                                                                   adb=adb,
                                                                   serial_number=serial_number)
        return self._iperf_factory.create(iperf_host, iperf_options, log_path)

    def setup_iperfs(self, iperfs):
        """
        Setup the iperf instance in-sequence.

        :param iperfs: iperf instance list
        :type iperfs: list
        :return: None
        """
        for iperf in iperfs:
            self.add_prerequisite(iperf)
        self.setup()

    @staticmethod
    def start(iperfs, force_port_available=False):
        """
        Start traffic in-sequence with iperf command.

        :param iperfs: iperf instance list
        :type iperfs: list
        :param force_port_available: kill iperf process if port in use, False by default
        :type force_port_available: bool
        :return: None
        """
        for iperf in iperfs:
            if force_port_available:
                iperf.force_port_available()
            iperf.start()

    def stop(self, iperfs, timeout=None, prior=StopPrior.Client, force=False):
        """
        Stop traffic in-sequence with iperf command.

        :param iperfs: iperf instance list
        :type iperfs: list
        :param timeout: timeout for per kill of a single iperf, 30s by default,
        at most there will be soft kill and hard kill,
        so the timeout will be from 30 ~ 60 seconds in real
        :type timeout: int
        :param prior: which type of the iperf instance will be stopped first,
        options are items in StopPrior, StopPrior.Client by default
        :type prior: StopPrior
        :param force: force to kill iperf process, False by default
        :type force: bool
        :return: None
        """
        if prior == StopPrior.Client:
            self._prior_iperf_client_objs_orders(iperfs)
        elif prior == StopPrior.Server:
            self._prior_iperf_server_objs_orders(iperfs)

        for iperf in iperfs:
            iperf.stop(timeout or 30, force)

    @staticmethod
    def _prior_iperf_server_objs_orders(iperfs):
        # cause True can be regarded as 1, and False can be regarded as 0, so reverse
        iperfs.sort(key=lambda iperf_obj: isinstance(iperf_obj, IperfServerTrafficGenerator), reverse=True)

    @staticmethod
    def _prior_iperf_client_objs_orders(iperfs):
        # cause True can be regarded as 1, and False can be regarded as 0, so reverse
        iperfs.sort(key=lambda iperf_obj: isinstance(iperf_obj, IperfClientTrafficGenerator), reverse=True)

    @staticmethod
    def is_running(iperf):
        return iperf.is_running()

    @staticmethod
    def get_output(iperf):
        """
        Get traffic output

        :param iperf: iperf instance
        :return: str with raw output
        """
        return iperf.get_output()

    def teardown_iperfs(self):
        """Teardown the iperf instance in-sequence and download iperf traffic statistic log."""
        self.teardown()
